import{_ as t,a0 as p,w as o,s as h,I as l,x as n,a1 as e,A as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何打包你的 Python 代码 | LCTT x X-CMD","titleTemplate":false,"description":"如何打包你的 Python 代码 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何打包你的 Python 代码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何打包你的 Python 代码 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211109 How to package your Python code","title":"如何打包你的 Python 代码","tag":"202111","desc":""},"relativePath":"202111/20211109 How to package your Python code.md","filePath":"[post].md"}'),r={name:"202111/20211109 How to package your Python code.md"};function u(g,s,b,c,y,k){const a=p("Link");return o(),h("div",null,[s[25]||(s[25]=l("h1",{id:"如何打包你的-python-代码",tabindex:"-1"},[n("如何打包你的 Python 代码 "),l("a",{class:"header-anchor",href:"#如何打包你的-python-代码","aria-label":"Permalink to “如何打包你的 Python 代码”"},"​")],-1)),s[26]||(s[26]=l("blockquote",null,[l("p",null,"使用 setuptools 来向用户交付 Python 代码。")],-1)),s[27]||(s[27]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202111/17/180249s8s1cnnn18gh3fsk.jpg",alt:""})],-1)),l("p",null,[s[1]||(s[1]=n("你花了几周的时间来完善你的代码。你已经对它进行了测试，并把它发送给一些亲近的开发者朋友以保证质量。你已经将所有的源代码发布在 ",-1)),e(a,{href:"https://opensource.com/life/16/8/how-construct-your-own-git-server-part-6"},{default:i(()=>[...s[0]||(s[0]=[n("你的个人 Git 服务器",-1)])]),_:1}),s[2]||(s[2]=n(" 上，并且从一些勇敢的早期使用者收到了一些有用的错误报告。现在你已经准备好将你的 Python 代码提供给全世界。",-1))]),s[28]||(s[28]=l("p",null,"就在这时你遇到一个问题。你不知道如何交付产品。",-1)),l("p",null,[s[5]||(s[5]=n("将代码交付给它的目标用户是一件大事。这是软件开发的一个完整的分支，是 CI/CD 中的 “D”，但很多人都忘记了，至少到最后才知道。我写过关于 ",-1)),e(a,{href:"https://opensource.com/article/19/7/introduction-gnu-autotools"},{default:i(()=>[...s[3]||(s[3]=[n("Autotools",-1)])]),_:1}),s[6]||(s[6]=n(" 和 ",-1)),e(a,{href:"https://opensource.com/article/21/5/cmake"},{default:i(()=>[...s[4]||(s[4]=[n("Cmake",-1)])]),_:1}),s[7]||(s[7]=n(" 的文章，但有些语言有自己的方法来帮助你将你的代码提供给用户。对于 Python 来说，向用户提供代码的一个常见方法是使用 ",-1)),s[8]||(s[8]=l("code",null,"setuptools",-1)),s[9]||(s[9]=n("。",-1))]),s[29]||(s[29]=d(`<h3 id="安装-setuptools" tabindex="-1">安装 setuptools <a class="header-anchor" href="#安装-setuptools" aria-label="Permalink to “安装 setuptools”">​</a></h3><p>安装和更新 <code>setuptools</code> 的最简单方法是使用 <code>pip</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo python -m pip install --upgrade setuptools</span></span></code></pre></div><h3 id="示例库" tabindex="-1">示例库 <a class="header-anchor" href="#示例库" aria-label="Permalink to “示例库”">​</a></h3><p>我创建了一个简单的 Python 库，名为 <code>myhellolib</code>，来作为需要打包的示例代码。这个库接受一个字符串，然后用大写字母打印出这个字符串。</p><p>它只有两行代码，但项目结构很重要，所以首先创建目录树：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir -p myhellolib.git/myhellolib</span></span></code></pre></div><p>为了确认这个项目是一个可导入的库（即 Python “模块”），在代码目录中创建一个空文件 <code>__init__.py</code>，同时创建一个包含代码的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch myhellolib.git/myhellolib/__init__.py</span></span>
<span class="line"><span>$ touch myhellolib.git/myhellolib/myhellolib.py</span></span></code></pre></div><p>在 <code>myhellolib.py</code> 文件中，输入简单的 Python 代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def greeter(s):</span></span>
<span class="line"><span>    print(s.upper())</span></span></code></pre></div><p>这就是写好的库。</p><h3 id="测试它" tabindex="-1">测试它 <a class="header-anchor" href="#测试它" aria-label="Permalink to “测试它”">​</a></h3><p>在打包之前，测试一下你的库。创建一个 <code>myhellolib.git/test.py</code> 文件并输入以下代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import myhellolib.myhellolib as hello</span></span>
<span class="line"><span>hello.greeter(&quot;Hello Opensource.com.&quot;)</span></span></code></pre></div><p>运行该脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd myhellolib.git</span></span>
<span class="line"><span>$ python ./test.py</span></span>
<span class="line"><span>HELLO OPENSOURCE.COM</span></span></code></pre></div><p>它可以工作，所以现在你可以把它打包了。</p><h3 id="setuptools" tabindex="-1">Setuptools <a class="header-anchor" href="#setuptools" aria-label="Permalink to “Setuptools”">​</a></h3><p>要用 <code>setuptools</code> 打包一个项目，你必须创建一个 <code>.toml</code> 文件，将 <code>setuptools</code> 作为构建系统。将这段文字放在项目目录下的 <code>myhellolib.toml</code> 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[build-system]</span></span>
<span class="line"><span>requires = [&quot;setuptools&quot;, &quot;wheel&quot;]</span></span>
<span class="line"><span>build-backend = &quot;setuptools.build_meta&quot;</span></span></code></pre></div><p>接下来，创建一个名为 <code>setup.py</code> 的文件，包含项目的元数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from setuptools import setup</span></span>
<span class="line"><span></span></span>
<span class="line"><span>setup(</span></span>
<span class="line"><span>   name=&#39;myhellolib&#39;,</span></span>
<span class="line"><span>   version=&#39;0.0.1&#39;,</span></span>
<span class="line"><span>   packages=[&#39;myhellolib&#39;],</span></span>
<span class="line"><span>   install_requires=[</span></span>
<span class="line"><span>      &#39;requests&#39;,</span></span>
<span class="line"><span>      &#39;importlib; python_version == &quot;3.8&quot;&#39;,</span></span>
<span class="line"><span>   ],</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>不管你信不信，这就是 <code>setuptools</code> 需要的所有设置。你的项目已经可以进行打包。</p><h3 id="打包-python" tabindex="-1">打包 Python <a class="header-anchor" href="#打包-python" aria-label="Permalink to “打包 Python”">​</a></h3><p>要创建你的 Python 包，你需要一个构建器。一个常见的工具是 <code>build</code>，你可以用 <code>pip</code> 安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python -m pip install build --user</span></span></code></pre></div><p>构建你的项目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python -m build</span></span></code></pre></div><p>过了一会儿，构建完成了，在你的项目文件夹中出现了一个新的目录，叫做 <code>dist</code>。这个文件夹包含一个 <code>.tar.gz</code> 和一个 <code>.whl</code> 文件。</p><p>这是你的第一个 Python 包! 下面是包的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar --list --file dist/myhellolib-0.0.1.tar.gz</span></span>
<span class="line"><span>myhellolib-0.0.1/</span></span>
<span class="line"><span>myhellolib-0.0.1/PKG-INFO</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib/</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib/__init__.py</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib/myhellolib.py</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib.egg-info/</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib.egg-info/PKG-INFO</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib.egg-info/SOURCES.txt</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib.egg-info/dependency_links.txt</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib.egg-info/requires.txt</span></span>
<span class="line"><span>myhellolib-0.0.1/myhellolib.egg-info/top_level.txt</span></span>
<span class="line"><span>myhellolib-0.0.1/setup.cfg</span></span>
<span class="line"><span>myhellolib-0.0.1/setup.py</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ unzip -l dist/myhellolib-0.0.1-py3-none-any.whl </span></span>
<span class="line"><span>Archive:  dist/myhellolib-0.0.1-py3-none-any.whl</span></span>
<span class="line"><span>Name</span></span>
<span class="line"><span>----</span></span>
<span class="line"><span>myhellolib/__init__.py</span></span>
<span class="line"><span>myhellolib/myhellolib.py</span></span>
<span class="line"><span>myhellolib-0.0.1.dist-info/METADATA</span></span>
<span class="line"><span>myhellolib-0.0.1.dist-info/WHEEL</span></span>
<span class="line"><span>myhellolib-0.0.1.dist-info/top_level.txt</span></span>
<span class="line"><span>myhellolib-0.0.1.dist-info/RECORD</span></span>
<span class="line"><span>-------</span></span>
<span class="line"><span>6 files</span></span></code></pre></div><h3 id="让它可用" tabindex="-1">让它可用 <a class="header-anchor" href="#让它可用" aria-label="Permalink to “让它可用”">​</a></h3><p>现在你知道了打包你的 Python 包是多么容易，你可以使用 Git 钩子、GitLab Web 钩子、Jenkins 或类似的自动化工具来自动完成这个过程。你甚至可以把你的项目上传到 PyPi，这个流行的 Python 模块仓库。一旦它在 PyPi 上，用户就可以用 <code>pip</code> 来安装它，就像你在这篇文章中安装 <code>setuptools</code> 和 <code>build</code> 一样！</p><p>当你坐下来开发一个应用或库时，打包并不是你首先想到的事情，但它是编程的一个重要方面。Python 开发者在程序员如何向世界提供他们的工作方面花了很多心思，没有比 <code>setuptools</code> 更容易的了。试用它，使用它，并继续用 Python 编码！</p><hr>`,36)),l("p",null,[s[11]||(s[11]=n("via: ",-1)),e(a,{href:"https://opensource.com/article/21/11/packaging-python-setuptools"},{default:i(()=>[...s[10]||(s[10]=[n("https://opensource.com/article/21/11/packaging-python-setuptools",-1)])]),_:1})]),l("p",null,[s[16]||(s[16]=n("作者：",-1)),e(a,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[12]||(s[12]=[n("Seth Kenlon",-1)])]),_:1}),s[17]||(s[17]=n(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[13]||(s[13]=[n("lujun9972",-1)])]),_:1}),s[18]||(s[18]=n(" 译者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[14]||(s[14]=[n("geekpi",-1)])]),_:1}),s[19]||(s[19]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[15]||(s[15]=[n("wxy",-1)])]),_:1})]),l("p",null,[s[22]||(s[22]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[20]||(s[20]=[n("LCTT",-1)])]),_:1}),s[23]||(s[23]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[21]||(s[21]=[n("Linux中国",-1)])]),_:1}),s[24]||(s[24]=n(" 荣誉推出",-1))])])}const P=t(r,[["render",u]]);export{C as __pageData,P as default};
